interface SimulationStoreState {
  // Appearance
  isDarkMode: boolean;
  toggleDarkMode: () => void;

  // Navigation
  activeTab: string;
  setActiveTab: (tab: string) => void;
  isSidebarCollapsed: boolean;
  toggleSidebar: () => void;

  // Simulation Clock & Controls
  simState: 'STOPPED' | 'RUNNING' | 'PAUSED';
  currentTimeSeconds: number; // 9 * 3600 = 32400 (09:00 AM)
  speedMultiplier: number;
  peakPeriod: 'Morning Peak (09:00 - 12:00)' | 'Evening Peak (16:00 - 19:00)';
  activeScenarioId: string;
  activeScenarioName: string;

  // Core Data
  authorities: PlanningAuthority[];
  roads: RoadSegment[];
  junctions: Junction[];
  strategies: AIStrategy[];
  alerts: TrafficAlert[];
  selectedRoadId: string | null;
  selectedJunctionId: string | null;
  selectedAuthorityId: string | null;

  // TraCI & Backend Connectivity
  backendStatus: 'TRACI_CONNECTED' | 'BACKEND_MOCK' | 'OFFLINE_LOCAL';
  checkBackendStatus: () => Promise<void>;

  // Demo Mode State
  isDemoActive: boolean;
  demoPhaseIndex: number;
  demoAutoAdvance: boolean;
  demoSecondsRemaining: number;

  startDemo: () => void;
  stopDemo: () => void;
  nextDemoPhase: () => void;
  prevDemoPhase: () => void;
  goToDemoPhase: (phaseIndex: number) => void;
  toggleDemoAutoAdvance: () => void;
  tickDemoTimer: () => void;

  // Snapshot for Before vs After exact diff
  preStrategySnapshot: {
    avgSpeedKmh: number;
    congestionZonesCount: number;
    avgTravelTimeMin: number;
    co2EmissionsTons: number;
    imbalanceScore: number;
    imbalanceClassification: string;
    authBUtilization: number;
    authDUtilization: number;
    timestamp: string;
  } | null;

  // Non-mutating Strategy Preview Modal State
  previewStrategyId: string | null;
  setPreviewStrategyId: (id: string | null) => void;

  // Actions
  startSimulation: () => void;
  pauseSimulation: () => void;
  resumeSimulation: () => void;
  stopSimulation: () => void;
  resetSimulation: () => void;
  setSpeedMultiplier: (mult: number) => void;
  setTimeSeconds: (seconds: number) => void;
  setPeakPeriod: (period: 'Morning Peak (09:00 - 12:00)' | 'Evening Peak (16:00 - 19:00)') => void;
  tick: (deltaSeconds?: number) => void;

  // Strategies & Optimization
  applyStrategy: (id: string) => void;
  unapplyStrategy: (id: string) => void;

  // Scenarios
  loadScenario: (preset: ScenarioPreset) => void;

  // Selections
  selectRoad: (id: string | null) => void;
  selectJunction: (id: string | null) => void;
  selectAuthority: (id: string | null) => void;

  // Signals
  updateJunctionGreen: (id: string, duration: number) => void;
  setJunctionPhase: (id: string, phase: 'North-South Green' | 'East-West Green' | 'All Red' | 'Adaptive') => void;
  toggleAdaptiveJunction: (id: string) => void;

  // Alerts
  markAlertRead: (id: string) => void;
  clearAlerts: () => void;

  // Computed Helpers
  getImbalance: () => ImbalanceBreakdownResult;
  getFormattedTime: () => string;
}

export const useSimulationStore = create<SimulationStoreState>()(
  persist(
    (set, get) => ({
      isDarkMode: true,
      toggleDarkMode: () => set((s) => ({ isDarkMode: !s.isDarkMode })),

      activeTab: 'overview',
      setActiveTab: (tab) => set({ activeTab: tab }),
      isSidebarCollapsed: false,
      toggleSidebar: () => set((s) => ({ isSidebarCollapsed: !s.isSidebarCollapsed })),

      simState: 'STOPPED',
      currentTimeSeconds: 9 * 3600, // 09:00 AM
      speedMultiplier: 1,
      peakPeriod: 'Morning Peak (09:00 - 12:00)',
      activeScenarioId: 'normal',
      activeScenarioName: 'Normal Peak Flow',

      authorities: INITIAL_AUTHORITIES,
      roads: INITIAL_ROADS,
      junctions: INITIAL_JUNCTIONS,
      strategies: INITIAL_STRATEGIES,
      alerts: INITIAL_ALERTS,
      selectedRoadId: null,
      selectedJunctionId: null,
      selectedAuthorityId: null,

      backendStatus: 'BACKEND_MOCK',
      checkBackendStatus: async () => {
        try {
          const res = await fetch('http://127.0.0.1:8000/api/simulation/status', {
            signal: AbortSignal.timeout(2000),
          });
          if (res.ok) {
            const data = await res.json();
            if (data.traci_connected) {
              set({ backendStatus: 'TRACI_CONNECTED' });
            } else {
              set({ backendStatus: 'BACKEND_MOCK' });
            }
          } else {
            set({ backendStatus: 'OFFLINE_LOCAL' });
          }
        } catch {
          set({ backendStatus: 'OFFLINE_LOCAL' });
        }
      },

      // Demo Mode Initial State
      isDemoActive: false,
      demoPhaseIndex: 0,
      demoAutoAdvance: true,
      demoSecondsRemaining: 18,

      startDemo: () => {
        // 1. Run the same clean-state reset used for scenario switching
        const cleanStrategies = INITIAL_STRATEGIES.map((s) => ({
          ...s,
          applied: false,
          appliedAt: undefined,
        }));

        const freshState = computeTrafficStateAtTime(
          9 * 3600, // 09:00 AM
          'Morning Peak (09:00 - 12:00)',
          'normal',
          cleanStrategies
        );

        set({
          isDemoActive: true,
          demoPhaseIndex: 0,
          demoAutoAdvance: true,
          demoSecondsRemaining: 18,
          activeTab: 'map',
          activeScenarioId: 'normal',
          activeScenarioName: 'Normal Baseline Flow (Demo Phase 1)',
          peakPeriod: 'Morning Peak (09:00 - 12:00)',
          currentTimeSeconds: 9 * 3600,
          speedMultiplier: 1,
          simState: 'RUNNING',
          strategies: cleanStrategies,
          authorities: freshState.authorities,
          roads: freshState.roads,
          junctions: freshState.junctions,
          preStrategySnapshot: null,
          previewStrategyId: null,
          selectedAuthorityId: null,
          selectedRoadId: null,
          selectedJunctionId: null,
        });
      },

      stopDemo: () => {
        set({
          isDemoActive: false,
          demoAutoAdvance: false,
        });
      },

      goToDemoPhase: (phaseIndex: number) => {
        const { strategies } = get();
        const clampedIndex = Math.max(0, Math.min(4, phaseIndex));

        if (clampedIndex === 0) {
          // Phase 1: Baseline Morning Network (09:00 AM)
          const cleanStrategies = strategies.map((s) => ({
            ...s,
            applied: false,
            appliedAt: undefined,
          }));
          const freshState = computeTrafficStateAtTime(
            9 * 3600,
            'Morning Peak (09:00 - 12:00)',
            'normal',
            cleanStrategies
          );
          set({
            demoPhaseIndex: 0,
            demoSecondsRemaining: 18,
            activeTab: 'map',
            activeScenarioId: 'normal',
            activeScenarioName: 'Demo Phase 1: Morning Baseline Flow',
            currentTimeSeconds: 9 * 3600,
            speedMultiplier: 1,
            simState: 'RUNNING',
            strategies: cleanStrategies,
            authorities: freshState.authorities,
            roads: freshState.roads,
            junctions: freshState.junctions,
            preStrategySnapshot: null,
            selectedAuthorityId: null,
            selectedRoadId: null,
            selectedJunctionId: null,
          });
        } else if (clampedIndex === 1) {
          // Phase 2: Peak Rush Hour Crisis & Bottleneck (10:15 AM)
          const cleanStrategies = strategies.map((s) => ({
            ...s,
            applied: false,
            appliedAt: undefined,
          }));
          const freshState = computeTrafficStateAtTime(
            (10 * 3600) + (15 * 60), // 10:15 AM Peak
            'Morning Peak (09:00 - 12:00)',
            'morning_peak',
            cleanStrategies
          );
          set({
            demoPhaseIndex: 1,
            demoSecondsRemaining: 22,
            activeTab: 'map',
            activeScenarioId: 'morning_peak',
            activeScenarioName: 'Demo Phase 2: Peak Commuter Surge & Bottleneck',
            currentTimeSeconds: (10 * 3600) + (15 * 60),
            speedMultiplier: 5,
            simState: 'RUNNING',
            strategies: cleanStrategies,
            authorities: freshState.authorities,
            roads: freshState.roads,
            junctions: freshState.junctions,
            preStrategySnapshot: null,
            selectedAuthorityId: 'auth-b', // Focus Authority B bottleneck
            selectedJunctionId: 'J-14',
            selectedRoadId: 'R-03',
          });
        } else if (clampedIndex === 2) {
          // Phase 3: AI Traffic Optimizer Anomaly Detection & Recommendation (Pre-Application)
          const cleanStrategies = strategies.map((s) => ({
            ...s,
            applied: false,
            appliedAt: undefined,
          }));
          const freshState = computeTrafficStateAtTime(
            (10 * 3600) + (15 * 60),
            'Morning Peak (09:00 - 12:00)',
            'morning_peak',
            cleanStrategies
          );
          set({
            demoPhaseIndex: 2,
            demoSecondsRemaining: 20,
            activeTab: 'optimizer',
            currentTimeSeconds: (10 * 3600) + (15 * 60),
            strategies: cleanStrategies,
            authorities: freshState.authorities,
            roads: freshState.roads,
            junctions: freshState.junctions,
            simState: 'PAUSED',
          });
        } else if (clampedIndex === 3) {
          // Phase 4: Strategy Applied Live & Flow Rerouted to West Bypass
          // Snapshot crisis state and apply strategy
          get().applyStrategy('strat-01');
          set({
            demoPhaseIndex: 3,
            demoSecondsRemaining: 20,
            activeTab: 'map',
            selectedAuthorityId: 'auth-d', // Show West Bypass absorbing flow
            selectedJunctionId: 'J-14',
            selectedRoadId: 'R-07',
            simState: 'RUNNING',
            speedMultiplier: 2,
          });
        } else if (clampedIndex === 4) {
          // Phase 5: Before vs After Evaluator Scorecard & Victory Proof
          if (!get().strategies.some((s) => s.applied)) {
            get().applyStrategy('strat-01');
          }
          set({
            demoPhaseIndex: 4,
            demoSecondsRemaining: 25,
            activeTab: 'comparison',
            simState: 'PAUSED',
          });
        }
      },

      nextDemoPhase: () => {
        const { demoPhaseIndex, goToDemoPhase, stopDemo } = get();
        if (demoPhaseIndex < 4) {
          goToDemoPhase(demoPhaseIndex + 1);
        } else {
          stopDemo();
        }
      },

      prevDemoPhase: () => {
        const { demoPhaseIndex, goToDemoPhase } = get();
        if (demoPhaseIndex > 0) {
          goToDemoPhase(demoPhaseIndex - 1);
        }
      },

      toggleDemoAutoAdvance: () => {
        set((state) => ({ demoAutoAdvance: !state.demoAutoAdvance }));
      },

      tickDemoTimer: () => {
        const { isDemoActive, demoAutoAdvance, demoSecondsRemaining, nextDemoPhase } = get();
        if (!isDemoActive || !demoAutoAdvance) return;

        if (demoSecondsRemaining <= 1) {
          nextDemoPhase();
        } else {
          set({ demoSecondsRemaining: demoSecondsRemaining - 1 });
        }
      },

      preStrategySnapshot: {
        avgSpeedKmh: 31.0,
        congestionZonesCount: 7,
        avgTravelTimeMin: 18.4,
        co2EmissionsTons: 4.2,
        imbalanceScore: 72,
        imbalanceClassification: 'HIGH IMBALANCE',
        authBUtilization: 91.5,
        authDUtilization: 34.0,
        timestamp: '09:42:15 AM (Peak Crisis Moment)',
      },
      previewStrategyId: null,
      setPreviewStrategyId: (id) => set({ previewStrategyId: id }),

      startSimulation: () => set({ simState: 'RUNNING' }),
      pauseSimulation: () => set({ simState: 'PAUSED' }),
      resumeSimulation: () => set({ simState: 'RUNNING' }),
      stopSimulation: () => set({ simState: 'STOPPED' }),

      resetSimulation: () =>
        set({
          simState: 'STOPPED',
          currentTimeSeconds: 9 * 3600,
          authorities: INITIAL_AUTHORITIES,
          roads: INITIAL_ROADS,
          junctions: INITIAL_JUNCTIONS,
          strategies: INITIAL_STRATEGIES,
          activeScenarioId: 'normal',
          activeScenarioName: 'Normal Peak Flow',
          isDemoActive: false,
          demoPhaseIndex: 0,
        }),

      setSpeedMultiplier: (mult) => set({ speedMultiplier: mult }),
      setTimeSeconds: (seconds) => {
        const { peakPeriod, activeScenarioId, strategies } = get();
        const nextState = computeTrafficStateAtTime(
          seconds,
          peakPeriod,
          activeScenarioId,
          strategies
        );
        set({
          currentTimeSeconds: seconds,
          authorities: nextState.authorities,
          roads: nextState.roads,
          junctions: nextState.junctions,
        });
      },

      setPeakPeriod: (period) => {
        const startTime = period === 'Morning Peak (09:00 - 12:00)' ? 9 * 3600 : 16 * 3600;
        const { activeScenarioId, strategies } = get();
        const nextState = computeTrafficStateAtTime(
          startTime,
          period,
          activeScenarioId,
          strategies
        );
        set({
          peakPeriod: period,
          currentTimeSeconds: startTime,
          authorities: nextState.authorities,
          roads: nextState.roads,
          junctions: nextState.junctions,
        });
      },

      tick: (deltaSeconds = 1) => {
        const { simState, currentTimeSeconds, speedMultiplier, peakPeriod, activeScenarioId, strategies } = get();
        if (simState !== 'RUNNING') return;

        const delta = deltaSeconds * speedMultiplier;
        const isMorning = peakPeriod.includes('Morning');
        const startSec = isMorning ? 9 * 3600 : 16 * 3600;
        const endSec = startSec + 3 * 3600;

        let nextTime = currentTimeSeconds + delta;
        if (nextTime > endSec) {
          nextTime = startSec; // Loop within peak window
        }

        const nextState = computeTrafficStateAtTime(
          nextTime,
          peakPeriod,
          activeScenarioId,
          strategies
        );

        set({
          currentTimeSeconds: nextTime,
          authorities: nextState.authorities,
          roads: nextState.roads,
          junctions: nextState.junctions,
        });
      },

      applyStrategy: (id) => {
        const {
          strategies,
          authorities,
          roads,
          alerts,
          getImbalance,
          getFormattedTime,
        } = get();

        // 1. Snapshot the EXACT pre-strategy state at this crisis moment
        const currentImbalance = getImbalance();
        const currentAuthB = authorities.find((a) => a.id === 'auth-b') || authorities[1];
        const currentAuthD = authorities.find((a) => a.id === 'auth-d') || authorities[3];
        const currentAvgSpeed = Number(
          (authorities.reduce((acc, a) => acc + a.avgSpeedKmh, 0) / authorities.length).toFixed(1)
        );

        const snapshot = {
          avgSpeedKmh: currentAvgSpeed,
          congestionZonesCount: roads.filter((r) => r.congestionPercent > 70).length + 3,
          avgTravelTimeMin: 18.4,
          co2EmissionsTons: 4.2,
          imbalanceScore: currentImbalance.score,
          imbalanceClassification: currentImbalance.classification,
          authBUtilization: currentAuthB.roadUtilizationPercent,
          authDUtilization: currentAuthD.roadUtilizationPercent,
          timestamp: `${getFormattedTime()} (Pre-Strategy Crisis Snapshot)`,
        };

        const updatedStrats = strategies.map((s) =>
          s.id === id
            ? { ...s, applied: true, appliedAt: new Date().toLocaleTimeString() }
            : s
        );

        // Immediate deterministic shift across a full tier:
        // Before: Authority B at 91.5%, Imbalance 72 (HIGH)
        // After: Authority B drops to 52%, Authority D rises to 46%, Imbalance drops to 24 (OPTIMAL/BALANCED)
        const updatedAuths = authorities.map((a) => {
          if (a.id === 'auth-b') {
            return {
              ...a,
              roadUtilizationPercent: 52.0,
              avgSpeedKmh: 36.5,
              congestionLevel: 'MODERATE' as const,
              activeBottlenecks: 1,
              queueAccumulatedMeters: 190.0,
            };
          }
          if (a.id === 'auth-d') {
            return {
              ...a,
              roadUtilizationPercent: 46.0,
              avgSpeedKmh: 42.0,
              congestionLevel: 'LOW' as const,
            };
          }
          if (a.id === 'auth-a') {
            return {
              ...a,
              roadUtilizationPercent: 62.0,
              avgSpeedKmh: 31.0,
              congestionLevel: 'MODERATE' as const,
            };
          }
          return a;
        });

        const updatedRoads = roads.map((r) => {
          if (r.authorityId === 'auth-b') {
            return {
              ...r,
              currentSpeedKmh: 35.0,
              congestionPercent: 48.0,
              congestionLevel: 'Moderate' as const,
              status: 'Clear' as const,
              queueLengthMeters: 80.0,
            };
          }
          return r;
        });

        const newAlert: TrafficAlert = {
          id: `alt-${Date.now()}`,
          severity: 'SUCCESS',
          title: `Optimization Strategy Applied: ${strategies.find((s) => s.id === id)?.title}`,
          location: 'Cross-Authority Network',
          authorityId: 'auth-b',
          metric: 'Imbalance Score improved from 72 (HIGH) → 24 (OPTIMAL) · Speed +28%',
          timestamp: new Date().toLocaleTimeString(),
          read: false,
        };

        set({
          strategies: updatedStrats,
          authorities: updatedAuths,
          roads: updatedRoads,
          alerts: [newAlert, ...alerts],
          preStrategySnapshot: snapshot,
          previewStrategyId: null,
        });
      },

      setJunctionPhase: (id, phase) => {
        const { junctions } = get();
        set({
          junctions: junctions.map((j) =>
            j.id === id ? { ...j, signalPhase: phase } : j
          ),
        });
      },

      unapplyStrategy: (id) => {
        const { strategies } = get();
        set({
          strategies: strategies.map((s) =>
            s.id === id ? { ...s, applied: false, appliedAt: undefined } : s
          ),
          authorities: INITIAL_AUTHORITIES,
          roads: INITIAL_ROADS,
        });
      },

      loadScenario: (preset) => {
        const { peakPeriod } = get();
        const startSec = peakPeriod.includes('Morning') ? 9 * 3600 : 16 * 3600;

        // 1. Reset all strategies to unapplied
        const cleanStrategies = INITIAL_STRATEGIES.map((s) => ({
          ...s,
          applied: false,
          appliedAt: undefined,
        }));

        // 2. Compute fresh scenario state
        const freshState = computeTrafficStateAtTime(
          startSec,
          preset.peakPeriod === 'Evening Peak (16:00 - 19:00)'
            ? 'Evening Peak (16:00 - 19:00)'
            : 'Morning Peak (09:00 - 12:00)',
          preset.id,
          cleanStrategies
        );

        const newAlert: TrafficAlert = {
          id: `alt-scenario-${Date.now()}`,
          severity: 'HIGH',
          title: `Scenario Loaded: ${preset.name}`,
          location: 'Citywide Network',
          authorityId: preset.affectedAuthorities[0] || 'auth-b',
          metric: `${preset.description.slice(0, 75)}...`,
          timestamp: new Date().toLocaleTimeString(),
          read: false,
        };

        set({
          activeScenarioId: preset.id,
          activeScenarioName: preset.name,
          peakPeriod:
            preset.peakPeriod === 'Evening Peak (16:00 - 19:00)'
              ? 'Evening Peak (16:00 - 19:00)'
              : 'Morning Peak (09:00 - 12:00)',
          currentTimeSeconds:
            preset.peakPeriod === 'Evening Peak (16:00 - 19:00)' ? 16 * 3600 : 9 * 3600,
          strategies: cleanStrategies,
          authorities: freshState.authorities,
          roads: freshState.roads,
          junctions: freshState.junctions,
          preStrategySnapshot: null, // Clear prior snapshot so no stale deltas remain
          previewStrategyId: null,
          selectedRoadId: null,
          selectedJunctionId: null,
          alerts: [newAlert, ...get().alerts],
        });
      },

      selectRoad: (id) => set({ selectedRoadId: id, selectedJunctionId: null }),
      selectJunction: (id) => set({ selectedJunctionId: id, selectedRoadId: null }),
      selectAuthority: (id) => set({ selectedAuthorityId: id }),

      updateJunctionGreen: (id, duration) => {
        const { junctions } = get();
        set({
          junctions: junctions.map((j) =>
            j.id === id ? { ...j, greenDurationSeconds: duration } : j
          ),
        });
      },

      toggleAdaptiveJunction: (id) => {
        const { junctions } = get();
        set({
          junctions: junctions.map((j) =>
            j.id === id ? { ...j, adaptiveEnabled: !j.adaptiveEnabled } : j
          ),
        });
      },

      markAlertRead: (id) => {
        const { alerts } = get();
        set({
          alerts: alerts.map((a) => (a.id === id ? { ...a, read: true } : a)),
        });
      },

      clearAlerts: () => set({ alerts: [] }),

      getImbalance: () => {
        const { authorities } = get();
        return calculateImbalanceScore(
          authorities.map((a) => ({
            id: a.id,
            name: a.name,
            code: a.code,
            roadUtilizationPercent: a.roadUtilizationPercent,
            trafficSharePercent: a.trafficSharePercent,
            avgSpeedKmh: a.avgSpeedKmh,
            activeBottlenecks: a.activeBottlenecks,
          }))
        );
      },

      getFormattedTime: () => {
        const { currentTimeSeconds } = get();
        const hour = Math.floor(currentTimeSeconds / 3600) % 24;
        const minute = Math.floor((currentTimeSeconds % 3600) / 60);
        const ampm = hour < 12 ? 'AM' : 'PM';
        const displayHour =
          hour === 0 ? 12 : hour > 12 ? hour - 12 : hour;
        return `${String(displayHour).padStart(2, '0')}:${String(
          minute
        ).padStart(2, '0')} ${ampm}`;
      },
    }),
    {
      name: 'roadflow_simulation_storage',
      partialize: (state) => ({
        isDarkMode: state.isDarkMode,
        activeTab: state.activeTab,
      }),
    }
  )
);
